sp_widget.client_script:
api.controller=function($scope) {
	var g_form = $scope.page.g_form;
	var input_step = g_form.getValue('current_step');
	var c = this;

	c.setSectionVisible = function(step) {
		c.current_step = step;
		c.setSectionItem();
	},

    c.setSectionItem = function() {
		//Step 1
		g_form.setDisplay('selected_country', c.current_step == '1' ? true: false);
		g_form.setDisplay('city', c.current_step == '1' ? true: false);
		g_form.setDisplay('company', c.current_step == '1' ? true: false);

		//Step 2
		g_form.setDisplay('step_2_input', c.current_step == '2' ? true: false);

		//Step 3
		g_form.setDisplay('step_3_input', c.current_step == '3' ? true: false);

		//Step 4
		g_form.setDisplay('step_4_input', c.current_step == '4' ? true: false);

		//Step 5
		g_form.setDisplay('step_5_input', c.current_step == '5' ? true: false);

		//Step 6
		g_form.setDisplay('step_6_input', c.current_step == '6' ? true: false);
	}

	c.setSectionVisible(input_step);// default
};

sp_widget.css:
.btn-breadcrumb .btn:not(:last-child):after {
  content: " ";
  display: block;
  width: 0;
  height: 0;
  border-top: 17px solid transparent;
  border-bottom: 17px solid transparent;
  border-left: 10px solid white;
  position: absolute;
  top: 50%;
  margin-top: -17px;
  left: 100%;
  z-index: 3;
}
.btn-breadcrumb .btn:not(:last-child):before {
  content: " ";
  display: block;
  width: 0;
  height: 0;
  border-top: 17px solid transparent;
  border-bottom: 17px solid transparent;
  border-left: 10px solid rgb(173, 173, 173);
  position: absolute;
  top: 50%;
  margin-top: -17px;
  margin-left: 1px;
  left: 100%;
  z-index: 3;
}

/** The Spacing **/
.btn-breadcrumb .btn {
  height:34px;
  padding:6px 12px 6px 24px;
  font-size:16px;
}
.btn-breadcrumb .btn:first-child {
  padding:6px 6px 6px 10px;
}
.btn-breadcrumb .btn:last-child {
  padding:6px 18px 6px 24px;
}

/** Default button **/
.btn-breadcrumb .btn.btn-default:not(:last-child):after {
  border-left: 10px solid #fff;
}
.btn-breadcrumb .btn.btn-default:not(:last-child):before {
  border-left: 10px solid #ccc;
}
.btn-breadcrumb .btn.btn-default:hover:not(:last-child):after {
  border-left: 10px solid #ebebeb;
}
.btn-breadcrumb .btn.btn-default:hover:not(:last-child):before {
  border-left: 10px solid #adadad;
}
/** 原来的箭头和按钮样式保持不变 **/

/* 选中状态 Active */
.btn-breadcrumb .btn.active {
  background-color: #007bff;  /* 蓝色背景 */
  color: #fff;                 /* 白色文字 */
  border-color: #007bff;       /* 边框蓝色 */
}

/* Active 状态箭头 */
.btn-breadcrumb .btn.active:not(:last-child):after {
  border-left: 10px solid #007bff;  /* 箭头尖端 */
}

.btn-breadcrumb .btn.active:not(:last-child):before {
  border-left: 10px solid #0056b3;  /* 箭头阴影/边框 */
}

/* Active 状态 Hover（可选，让蓝色稍亮） */
.btn-breadcrumb .btn.active:hover:not(:last-child):after {
  border-left: 10px solid #339aff;
}

.btn-breadcrumb .btn.active:hover:not(:last-child):before {
  border-left: 10px solid #004080;
}
